INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('7de71850-7dfa-4c8b-94f0-d00a18aa3abb', 'ACP-Q-0012', 1, 'published', 'p-mpharm', 'sub-hf', 'easy', 'sba', 'community', 'human', 1789734485, 1789734485, 1789734485);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('30d506da-fcfc-4d92-8ea9-f837dc11f80b', '7de71850-7dfa-4c8b-94f0-d00a18aa3abb', 'A 34-year-old male patient with non-valvular atrial fibrillation has a CHA2DS2-VASc score of 4 and an ORBIT score of 3. Renal function reveals a CrCl of 42 mL/min. (Case Ref: CARDIOVASCULAR-0012). Relevant physiological and medication history have been reviewed.', 'What is the most appropriate anticoagulation strategy according to NICE NG196?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('906febfe-f585-4a99-b5ec-81b5dea364b1', '7de71850-7dfa-4c8b-94f0-d00a18aa3abb', 'A', 'Apixaban 5 mg twice daily (or standard DOAC dose adjusted for renal function)', 1, 'Correct. A Direct-acting Oral Anticoagulant (DOAC) is first-line over warfarin for non-valvular AF. For apixaban, dose reduction to 2.5 mg bd is only triggered if 2 of 3 criteria apply: age >= 80, weight <= 60kg, serum creatinine >= 133 mcmol/L.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('90b21d55-ca2b-4ac7-a198-5ea6c01a98b4', '7de71850-7dfa-4c8b-94f0-d00a18aa3abb', 'B', 'Warfarin with target INR 2.0 to 3.0', 0, 'Sub-optimal. DOACs demonstrate superior or non-inferior safety and efficacy with lower intracranial haemorrhage rates compared to warfarin.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('863a0fb0-6455-43cc-a8fe-d9b2052f7e71', '7de71850-7dfa-4c8b-94f0-d00a18aa3abb', 'C', 'Aspirin 75 mg daily monotherapy', 0, 'Contraindicated. Aspirin monotherapy is explicitly contraindicated for stroke prevention in AF because it provides negligible stroke reduction while increasing major bleeding.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('156acb03-f470-4e4d-a1fd-31cf74f0dc43', '7de71850-7dfa-4c8b-94f0-d00a18aa3abb', 'D', 'Dual antiplatelet therapy (Aspirin + Clopidogrel)', 0, 'Deprecated historical alternative. Clinical trials established that DAPT is inferior to oral anticoagulants and causes similar major bleeding.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2c4466e5-10c4-4a9a-ae44-25cdd761c71d', '7de71850-7dfa-4c8b-94f0-d00a18aa3abb', 'E', 'Rivaroxaban 20 mg once daily with no meal instructions or renal dose adjustment', 0, 'Inappropriate administration. Rivaroxaban 15mg/20mg tablets must always be taken with food for adequate bioavailability; at CrCl 42 mL/min, the dose should be reduced to 15 mg daily.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('8176b8ae-fb83-4ad8-acf9-c17010cf406c', '7de71850-7dfa-4c8b-94f0-d00a18aa3abb', 'DOACs are first-line for stroke prevention in non-valvular AF. Never use antiplatelet monotherapy for AF stroke prophylaxis.', 'Always calculate CrCl using Cockcroft-Gault equation with actual body weight, not eGFR. Reference: NICE NG196: Atrial fibrillation (Section 1.6).', 'NICE NG196: Atrial fibrillation (Section 1.6)', 1789734485, 1789734485);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('114b474c-79b1-4399-ba52-5d510c28b0f6', '7de71850-7dfa-4c8b-94f0-d00a18aa3abb', 1789734485, 1789734485, 1789734485, 1789734485, 0, 1789734485, 1789734485);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('4a411fcc-aff6-4f13-8358-4947b5231f89', 'ACP-Q-0013', 1, 'published', 'p-mpharm', 'sub-af', 'hard', 'sba', 'gp', 'human', 1789734485, 1789734485, 1789734485);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('160c7b1b-b6bd-4620-abd0-5c3f0a07d548', '4a411fcc-aff6-4f13-8358-4947b5231f89', 'A 41-year-old female patient presents for a medication review following clinic blood pressure measurements averaging 156/96 mmHg (Stage 2 hypertension) confirmed by ABPM. There is no past history of diabetes or proteinuric kidney disease. (Case Ref: CARDIOVASCULAR-0013). Relevant physiological and medication history have been reviewed.', 'In accordance with NICE NG136 guidance, which of the following is the most appropriate initial antihypertensive therapy?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f049d73d-95f2-4cfb-8dad-f247e0c50394', '4a411fcc-aff6-4f13-8358-4947b5231f89', 'A', 'Amlodipine 5 mg orally once daily', 1, 'Correct. For patients of Black African or African-Caribbean family origin (any age) or adults aged 50 and over without diabetes, Step 1 treatment is a Calcium Channel Blocker (CCB).', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('523e605b-e8d0-46b8-bc6f-e06a28fbe79f', '4a411fcc-aff6-4f13-8358-4947b5231f89', 'B', 'Ramipril 2.5 mg orally once daily', 0, 'Sub-optimal. ACE inhibitors or ARBs are first-line for non-Black patients under 55 or adults with type 2 diabetes of any age, but less effective as monotherapy in Black African ancestry.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a30d85bf-d2c1-4849-83be-2a561f5bb7b9', '4a411fcc-aff6-4f13-8358-4947b5231f89', 'C', 'Bisoprolol 5 mg orally once daily', 0, 'Contraindicated as first-line monotherapy. Beta-blockers are no longer recommended as routine initial monotherapy under NICE NG136 unless there is a compelling cardiac co-indication.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('77fa3abf-e747-4415-a023-3ea5f45126a6', '4a411fcc-aff6-4f13-8358-4947b5231f89', 'D', 'Atenolol 50 mg orally once daily', 0, 'Deprecated historical practice. Atenolol has shown inferior stroke reduction in trials compared to modern CCB/ACEi regimens.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('05d9a76c-0ff5-4020-9560-19fd7986374a', '4a411fcc-aff6-4f13-8358-4947b5231f89', 'E', 'Amlodipine 10 mg with no repeat blood pressure monitoring for 12 months', 0, 'Inappropriate dosing and monitoring. Starting at the maximum 10 mg increases ankle oedema risk, and NICE mandates review within 4 to 8 weeks.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('f925d4de-8616-4b93-9ecf-0e27d5eb04e3', '4a411fcc-aff6-4f13-8358-4947b5231f89', 'NICE NG136 Step 1: CCB is first-line in patients of Black African origin or patients aged 55+ without diabetes.', 'Blood pressure treatment steps: Step 1 (A/C), Step 2 (A+C or A+D), Step 3 (A+C+D), Step 4 (add low-dose spironolactone if K+ <= 4.5 or alpha/beta-blocker if K+ > 4.5). Reference: NICE NG136: Hypertension in adults (Section 1.4).', 'NICE NG136: Hypertension in adults (Section 1.4)', 1789734485, 1789734485);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('06a9daef-794c-4abd-b92f-fad88e26e816', '4a411fcc-aff6-4f13-8358-4947b5231f89', 1789734485, 1789734485, 1789734485, 1789734485, 0, 1789734485, 1789734485);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('1caa3077-3e9a-41b7-81dd-698a95fba3b1', 'ACP-Q-0014', 1, 'published', 'p-mpharm', 'sub-lipid', 'easy', 'sba', 'community', 'human', 1789734485, 1789734485, 1789734485);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('b66db0ce-b1a3-4b26-af13-6acb75fff75b', '1caa3077-3e9a-41b7-81dd-698a95fba3b1', 'A 48-year-old male patient with newly diagnosed HFrEF (ejection fraction 32%) is currently symptomatically stable on Ramipril 10 mg and Bisoprolol 5 mg. Current eGFR is 54 mL/min and serum potassium is 4.4 mmol/L. (Case Ref: CARDIOVASCULAR-0014). Relevant physiological and medication history have been reviewed.', 'Which addition to the current regimen is recommended by UK guidance to reduce mortality and hospitalisation?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f5d1b570-b18a-42e5-b3b7-4865fcae6037', '1caa3077-3e9a-41b7-81dd-698a95fba3b1', 'A', 'Initiate Dapagliflozin 10 mg once daily and Spironolactone 25 mg once daily', 1, 'Correct. Modern guideline-directed medical therapy (GDMT) mandates foundation quad-therapy: ACEi/ARNI, beta-blocker, MRA (spironolactone), and SGLT2 inhibitor (dapagliflozin/empagliflozin).', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d9a1de0b-f471-46d3-bc60-4fbe28ae4d56', '1caa3077-3e9a-41b7-81dd-698a95fba3b1', 'B', 'Increase Bisoprolol to 10 mg and withhold additional medication classes', 0, 'Sub-optimal. While beta-blocker uptitration is beneficial, rapid multi-class quad-therapy initiation confers greater early mortality reduction.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ac68516a-6eb5-4a03-bfd2-64347eb733ac', '1caa3077-3e9a-41b7-81dd-698a95fba3b1', 'C', 'Add Verapamil 120 mg modified-release daily for blood pressure control', 0, 'Strictly contraindicated. Non-dihydropyridine CCBs (verapamil, diltiazem) have negative inotropic effects and worsen outcomes in HFrEF.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bd079efa-1392-41e0-8e0e-5f3099f3c0ab', '1caa3077-3e9a-41b7-81dd-698a95fba3b1', 'D', 'Add Digoxin 125 mcg daily as initial second-line therapy', 0, 'Deprecated historical usage. Digoxin does not reduce mortality in HFrEF; it is reserved for symptom control in refractory patients or AF rate control.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e2ce0dfa-e8cd-45f6-a504-6faf9aa40406', '1caa3077-3e9a-41b7-81dd-698a95fba3b1', 'E', 'Start Spironolactone 50 mg without checking U&Es at 1 and 4 weeks', 0, 'Inappropriate monitoring and starting dose. Initial dose should be 25 mg with strict baseline and early potassium/creatinine re-checks to avoid fatal hyperkalaemia.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('ff38c97f-1a12-471a-b385-04881960959a', '1caa3077-3e9a-41b7-81dd-698a95fba3b1', 'HFrEF foundation quad-therapy includes ACEi/ARNI, Beta-blocker, MRA, and SGLT2 inhibitor.', 'Check renal function and electrolytes before and 1-2 weeks after initiating or increasing MRAs. Reference: NICE NG106 & ESC Heart Failure Guidelines.', 'NICE NG106 & ESC Heart Failure Guidelines', 1789734485, 1789734485);
