INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('0b17b729-2b76-473c-a3a9-eaf3e80791d5', '03dcc55c-b191-4b90-b207-1369a61ee3ca', 'A hospital patient is prescribed 1 litre of sodium chloride 0.9% containing 40 mmol potassium chloride to be infused over 8 hours. The giving set delivers 20 drops per mL. (Case Ref: CALCULATIONS-0178). Relevant physiological and medication history have been reviewed.', 'What is the required infusion rate in drops per minute (drops/min)? Round to the nearest whole drop.', '42', '1', 'drops/min', NULL, 1, '(1000 * 20) / (8 * 60) = 20000 / 480 = 41.67 drops/min = 42 drops/min.', 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4acfd264-0ac6-4b99-ac9b-98121bb7345c', '03dcc55c-b191-4b90-b207-1369a61ee3ca', 'A', '42 drops/min', 1, 'Correct. Total volume = 1,000 mL. Total time = 8 hours * 60 minutes = 480 minutes. Total drops = 1,000 mL * 20 drops/mL = 20,000 drops. 20,000 / 480 = 41.67 drops/min = 42 drops/min.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3c53dbeb-2445-44f3-9b63-eaff4141aa13', '03dcc55c-b191-4b90-b207-1369a61ee3ca', 'B', '21 drops/min (calculated based on 10 drops/mL giving set)', 0, 'Incorrect giving set factor used.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('460c21a4-4cac-43e7-acd5-1d92ad2ab6fc', '03dcc55c-b191-4b90-b207-1369a61ee3ca', 'C', '83 drops/min (exceeds safe maximum IV potassium infusion rate of 20 mmol/hr)', 0, 'Unsafe infusion rate causing cardiac arrest risk from rapid potassium administration.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6ab186b3-e41b-431e-94f3-b362985c361f', '03dcc55c-b191-4b90-b207-1369a61ee3ca', 'D', '125 drops/min (infused over 2 hours instead of 8 hours)', 0, 'Dangerous rate violation.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8d5eebbc-e255-423a-a7e5-761168a5d3f0', '03dcc55c-b191-4b90-b207-1369a61ee3ca', 'E', '50 drops/min', 0, 'Rounding error resulting in infusion completing ahead of schedule.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('3bc2f5b1-93f6-419e-9fd6-fdb21bffcc68', '03dcc55c-b191-4b90-b207-1369a61ee3ca', 'Infusion rate (drops/min) = (Volume in mL * Drop factor) / (Time in hours * 60).', 'Maximum peripheral potassium infusion rate should generally not exceed 10 to 20 mmol/hour. Reference: BNF Chapter 9 / GPhC Paper 1 Standards.', 'BNF Chapter 9 / GPhC Paper 1 Standards', 1789734485, 1789734485);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('194e92cc-f81e-40a5-bdd3-2bb33fde7305', '03dcc55c-b191-4b90-b207-1369a61ee3ca', 1789734485, 1789734485, 1789734485, 1789734485, 0, 1789734485, 1789734485);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('2d9d438e-9e9b-4196-9eb5-ef70082715df', 'ACP-Q-0179', 1, 'published', 'p-mpharm', 'sub-dilutions', 'hard', 'calculation', 'gp', 'human', 1789734485, 1789734485, 1789734485);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('4d68aba4-f122-4371-a274-7c4a48a021aa', '2d9d438e-9e9b-4196-9eb5-ef70082715df', 'A 74-year-old female patient weighing 58 kg presents with serum creatinine of 115 micromol/L. She is being assessed for apixaban stroke prevention in non-valvular atrial fibrillation. (Case Ref: CALCULATIONS-0179). Relevant physiological and medication history have been reviewed.', 'Calculate the patient’s estimated creatinine clearance (CrCl) in mL/min using the Cockcroft-Gault formula. Give your answer to the nearest whole number.', '37', '1', 'mL/min', NULL, 1, '((140 - 74) * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 mL/min. With 1.04 constant = 37.3 mL/min.', 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('49570679-d094-40be-9621-135411570561', '2d9d438e-9e9b-4196-9eb5-ef70082715df', 'A', '37 mL/min', 1, 'Correct. Cockcroft-Gault formula: ((140 - Age) * Weight in kg * 1.04) / Serum Creatinine in micromol/L. ((140 - 74) * 58 * 1.04) / 115 = (66 * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 -> adjusted for female factor = 37.8 mL/min (approx 35-37 mL/min depending on constant 1.04 vs 0.85).', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0e86d1af-819c-4307-82d3-af2fcd77db6c', '2d9d438e-9e9b-4196-9eb5-ef70082715df', 'B', '44 mL/min (omitted female correction factor of 1.04 vs 1.23 for males)', 0, 'Incorrect. Forgets female adjustment factor (1.04).', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e0b4796e-fb71-434b-9b6a-63b015b2b785', '2d9d438e-9e9b-4196-9eb5-ef70082715df', 'C', '52 mL/min (used MDRD eGFR instead of Cockcroft-Gault CrCl)', 0, 'Clinically unsafe. MHRA specifically warns against using eGFR for drug dosing in older adults or extreme weights.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d77a7b47-5fa3-4835-9e8d-db014e8749e1', '2d9d438e-9e9b-4196-9eb5-ef70082715df', 'D', '25 mL/min (severe underestimation)', 0, 'Calculation error leading to inappropriate drug discontinuation.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('b9f8443e-18a2-4b98-8c9c-5088b56b9a83', '2d9d438e-9e9b-4196-9eb5-ef70082715df', 'E', '60 mL/min (assumed normal without calculation)', 0, 'Presuming renal clearance based purely on age without calculation is clinically dangerous.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('04642efc-e20e-4022-9d71-f1333fbbb094', '2d9d438e-9e9b-4196-9eb5-ef70082715df', 'Always use the Cockcroft-Gault formula for renal dose adjustments: Male: ((140-age)*wt*1.23)/Cr; Female: ((140-age)*wt*1.04)/Cr.', 'Units: Age (years), Weight (kg), Serum Creatinine (micromol/L). Reference: GPhC Calculations Guidance & BNF Dosing Framework.', 'GPhC Calculations Guidance & BNF Dosing Framework', 1789734485, 1789734485);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('a41622b6-ff71-4fec-bea9-b80a1c78828e', '2d9d438e-9e9b-4196-9eb5-ef70082715df', 1789734485, 1789734485, 1789734485, 1789734485, 0, 1789734485, 1789734485);
